// Helpers for checks that scan source *code* for a forbidden token (a banned
// API, an impure import, a DOM specific). Such a check must see code, not
// prose: a comment or a doc-string that merely *names* `chrome.storage` or
// `fetch(` is describing the code, not doing it, and matching it is a false
// positive that fails the build over an English sentence. Strip comments first.

// A `/` opens a regex literal only where a value may begin. After a value - 
// an identifier, a number, a closing `)` or `]` - it is division. The keywords
// are the identifiers that are not values, so the `/` after them opens a regex.
const VALUE_END = /[\w$)\]]$/;
const NOT_A_VALUE = /\b(return|typeof|instanceof|in|of|new|delete|void|case|do|else|yield|await)$/;
function opensRegex(code) {
  const before = code.replace(/\s+$/, '');
  if (before === '') return true;
  if (!VALUE_END.test(before)) return true;
  return NOT_A_VALUE.test(before);
}

// Return `source` with its JS/TS comments removed, leaving everything else —
// including string, template and regex literals - byte-for-byte intact.
// Literal-aware on purpose: a `//` inside "https://…" is not a comment, and
// dropping the rest of that line would corrupt real code (and could hide a
// genuine violation that follows on the same line). The same holds inside a
// regex, whose `"`, `'` and `` ` `` are pattern characters - reading one as a
// string's opening quote puts the scanner in string state for the rest of the
// file, where every later comment survives and every later string reads as code.
// Newlines inside block comments are kept so line numbers don't shift.
export function stripComments(source) {
  let out = '';
  let state = 'code'; // code | line | block | sq | dq | tpl | re | reClass
  // One frame per `${}` hole still open, innermost last, each holding the brace
  // depth reached inside it. A hole holds code, and that code may open a template
  // of its own, so the enclosing template is a place to return to rather than a
  // flag: without the stack the inner literal's backtick closed the outer one and
  // every character after it read inside-out.
  const holes = [];
  for (let i = 0; i < source.length; i++) {
    const c = source[i];
    const c2 = source[i + 1];
    if (state === 'code') {
      if (c === '/' && c2 === '/') { state = 'line'; i++; continue; }
      if (c === '/' && c2 === '*') { state = 'block'; i++; continue; }
      if (c === '/' && opensRegex(out)) state = 're';
      else if (c === "'") state = 'sq';
      else if (c === '"') state = 'dq';
      else if (c === '`') state = 'tpl';
      else if (holes.length && c === '{') holes[holes.length - 1].depth++;
      else if (holes.length && c === '}') {
        if (holes[holes.length - 1].depth === 0) { holes.pop(); state = 'tpl'; }
        else holes[holes.length - 1].depth--;
      }
      out += c;
    } else if (state === 're' || state === 'reClass') {
      // Inside a regex literal. A `/` inside a character class is a literal
      // slash, not the closing delimiter, so the class is tracked as its own
      // state rather than guessed at.
      out += c;
      if (c === '\\') { out += c2 ?? ''; i++; }
      else if (c === '\n') state = 'code'; // an unterminated regex was a division after all
      else if (state === 're' && c === '[') state = 'reClass';
      else if (state === 'reClass' && c === ']') state = 're';
      else if (state === 're' && c === '/') state = 'code';
    } else if (state === 'line') {
      if (c === '\n') { state = 'code'; out += c; }
    } else if (state === 'block') {
      if (c === '*' && c2 === '/') { state = 'code'; i++; }
      else if (c === '\n') out += c;
    } else {
      // Inside a string/template literal: copy through until the matching quote,
      // honoring backslash escapes so an escaped quote doesn't end it early.
      out += c;
      if (c === '\\') { out += c2 ?? ''; i++; }
      else if (state === 'tpl' && c === '$' && c2 === '{') {
        out += c2; i++;
        holes.push({ depth: 0 });
        state = 'code';
      } else if ((state === 'sq' && c === "'") || (state === 'dq' && c === '"') || (state === 'tpl' && c === '`')) {
        state = 'code';
      }
    }
  }
  return out;
}

// The extensions whose comments `stripComments` actually models. A file outside
// this set is never called comments-only: the parser cannot see its comments, so
// "nothing but comments changed" is a claim it has no grounds for, and answering
// "no" is the end that fails safe for both callers below.
export const COMMENT_CHECKABLE = new Set([
  '.mjs', '.cjs', '.js', '.jsx', '.ts', '.tsx', '.c', '.h', '.cc', '.cpp', '.hpp',
  '.java', '.go', '.swift', '.kt', '.dart', '.rs', '.cs', '.scss', '.css',
]);

// Did a change to `file` touch only its comments? `before`/`after` are the file's
// two contents, null where it was added or deleted — neither of which is a
// comment-only change, whatever the other side holds.
//
// Indentation and blank lines are ignored, so a whitespace-only edit inside a
// template literal reads as comments-only; in a language whose indentation is
// semantic the extension set above has already answered no.
//
// Its callers grant a PERMISSION on the answer — may this run land its own pull
// request unreviewed, may it have touched this file at all — which is why the safe
// end is "no" and why the answer lives here rather than in each of them.
export function commentOnly(file, before, after) {
  if (before == null || after == null) return false;
  const dot = file.lastIndexOf('.');
  const ext = dot === -1 ? '' : file.slice(dot).toLowerCase();
  if (!COMMENT_CHECKABLE.has(ext)) return false;
  const meat = (text) => stripComments(text).split('\n').map((l) => l.trim()).filter((l) => l !== '').join('\n');
  return meat(before) === meat(after);
}

import { basename } from 'node:path';
import { finding } from '../../../../engine/checks/helpers/findings.mjs';
import { COMMENT_CHECKABLE, commentOnly } from '../../../../engine/checks/helpers/code-scanning.mjs';

// The write-surface gate for the improve-comments pass. Its skill bounds every edit
// to comments in code files and to `README.md` documents; the pass runs unattended
// and writes the repo's OWN SOURCE — the one surface no other scheduled task
// touches — so the boundary needs a machine guarantee rather than a prose request.
//
// THE PERMISSION IS READ, NEVER ASSERTED. A file passes because its code is
// identical once the comments are stripped from both sides, not because the run
// says it only touched comments. That is the whole point: a run that quietly
// renamed a variable while "improving comments" is exactly what this catches, and
// a run cannot talk its way past a text comparison.
//
// THREE SHAPES FAIL, and each is deliberate rather than an oversight:
//   - a file whose language `commentOnly` cannot parse counts as code, so a comment
//     edit in one reds the run. Answering "I could not look" as a pass would make
//     the gate silently narrower than the languages a repo actually holds;
//   - an ADDED or DELETED code file is never comment-only, whatever it holds — a
//     whole file is a whole file, and this pass does not add or remove them;
//   - a DELETED `README.md` is not an improvement to a README. Modifying one is the
//     pass's business; deciding a document should not exist is not;
//   - ANY change under `.claudinite/shared/`, comment-only or not. The vendored
//     mount is not the repo's own source and the next update replaces it whole.
//     The task's precondition keeps it out of a round's scope; this is what holds
//     when a run reaches for it anyway. `.claudinite/local/` is the repo's own, and
//     is judged like any other file.
//
// RELEVANCE IS THE PINNED COMMIT SUBJECT, the same self-gating shape
// claudinite-growth's capture gate uses: the run marks itself, so this rule can run
// everywhere basics is declared — at the session Stop hook and on every PR — and
// costs ~nothing on a branch that is not this pass.
export const IMPROVE_COMMENTS_RUN = /^Claudinite tidy: improve comments/;

const isReadme = (p) => basename(p).toLowerCase() === 'readme.md';

// The same prefix the task's precondition filters its scope by (MOUNT_PREFIX in
// tasks/improve-comments/task.json); that task imports nothing, so the two are held
// in step by the test beside this check rather than by a shared constant.
export const MOUNT_PREFIX = '.claudinite/shared/';
const inMount = (p) => p.startsWith(MOUNT_PREFIX);

const rule = {
  id: 'improve-comments-scope',
  on_fail: 'block',
  scope: 'work',
  doc: 'packs/basics/skills/improve-comments/SKILL.md',
  description: 'An improve-comments run changes only comments in code files outside the .claudinite/ mount, and README.md documents',
  why: 'the pass runs unattended against the repo\'s own source, and its whole safety case is that a comment cannot change behaviour — a run that also moved a line has made an unreviewed code change wearing a housekeeping title',

  run(work) {
    if (work.onDefaultBranch()) return [];
    if (!work.commits.some((m) => IMPROVE_COMMENTS_RUN.test(m))) return [];

    const deleted = new Set(work.deleted);
    return [...new Set([...work.changedFiles, ...work.deleted])]
      .filter((p) => inMount(p) || (isReadme(p) ? deleted.has(p) : !commentOnly(p, work.readBase(p), work.read(p))))
      .sort()
      .map((p) => finding(rule, inMount(p)
        ? {
          file: p,
          what: `an improve-comments run changed ${p}, which is inside the ${MOUNT_PREFIX} mount`,
          fix: `revert ${p} — the mount is not this repo's source: the next update replaces it whole, so a comment improved there is gone by morning; take the change to the canon instead`,
        }
        : isReadme(p)
        ? {
          file: p,
          what: `an improve-comments run deleted ${p} — a README may be improved, never removed`,
          fix: 'restore the file; deciding a document should not exist is a change that gets reviewed, not a comment pass',
        }
        : unparseable(p)
          ? {
            file: p,
            what: `an improve-comments run changed ${p}, whose language the comment parser cannot read`,
            fix: `revert ${p} — outside the parser's set a file counts as code, so nothing here can show the change was only comments; leave them to a change that gets reviewed`,
          }
          : {
            file: p,
            what: work.readBase(p) === null || deleted.has(p)
              ? `an improve-comments run added or deleted ${p}, which is never a comment-only change`
              : `an improve-comments run changed more than the comments in ${p}`,
            fix: 'keep the branch to comment text in code files and to README.md content — a rename, a moved line or a reformat is its own change, with its own review',
          }));
  },
};

// Whether the file's language is one `commentOnly` can parse at all. Only used to
// pick the remedy: a run told "you changed more than comments" about a `.py` file
// it only commented would go looking for a code edit that isn't there.
function unparseable(p) {
  const dot = p.lastIndexOf('.');
  return !COMMENT_CHECKABLE.has(dot === -1 ? '' : p.slice(dot).toLowerCase());
}

export default [rule];

import overlayColorContrast from './overlay-color-contrast.mjs';
import renderedOverlaysUntracked from './rendered-overlays-untracked.mjs';
import panelScaleCalibration from './panel-scale-calibration.mjs';
import scaleNumbersMatchCalibration from './scale-numbers-match-calibration.mjs';
import lockedMetricFields from './locked-metric-fields.mjs';
import calibrationSingleSource from './calibration-single-source.mjs';
import renderOutputsGitignored from './render-outputs-gitignored.mjs';

// The project's own pack: the vessel-image quantification domain this repo works
// in - gP-CD31 red-channel confocal panels measured for categorize / count /
// measure. Declared by hand as `local/vascular-coloring`; detect/marker stay null.
//
// Check modules here stay dependency-free (plain finding objects, no engine
// import) so the pack loads without the gitignored shared mount.
export default {
  id: 'vascular-coloring',
  ruleRoutingGuidance: {
    belongs: 'vessel-image quantification — overlay appearance, render outputs, and the calibration that makes a number micrometres',
    excludes: 'the research-project class and the working lifecycle — those are canon packs',
  },
  detect: null,
  marker: null,
  prose: 'RULES.md',
  worldRules: [
    overlayColorContrast,
    renderedOverlaysUntracked,
    panelScaleCalibration,
    scaleNumbersMatchCalibration,
    lockedMetricFields,
    calibrationSingleSource,
    renderOutputsGitignored,
  ],
  skills: ['vessel-overlay-review', 'paper-intake', 'image-algorithm-development'],
};

